def xargs(cmd, varargs, color=False, target_concurrency=1, _max_length=_get_platform_max_length(), **kwargs):
    if color and _has_pty_support():
        pty = True
    else:
        pty = False
    pg = PartitionGenerator(target_concurrency, _max_length)
    for vararg in varargs:
        for partition in pg(vararg):
            process = subprocess.Popen(cmd + (partition,), shell=False, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, universal_newlines=True, close_fds=True, startupinfo=None if not pty else _get_su())
