    for i in range(0, len(cmd)):
        if i == 0:
            new_cmd += (cmd[i],)
        elif i == 1:
            if cmd[i].startswith('#!'):
                new_cmd += ('cmd.exe', '/C')
            else:
                new_cmd += (cmd[i],)
        else:
            new_cmd += (cmd[i],)
    return new_cmd

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    normalized_cmd = []
    for arg in cmd:
        if arg.startswith('#!'):
            arg = arg.replace('#!', 'python -c')
        elif arg.startswith('python'):
            arg = arg.replace('python', '/path/to/python')
        normalized_cmd.append(arg)
    return tuple(normalized_cmd)

