def ttl_cache_inner(func, maxsize, ttl, timer, typed):
    def wrapper(args, kwargs=None):
        key = func.__module__ + "." + func.__qualname__ + "(" + str(args) + "," + str(kwargs) + ")"
        decorator = TimeToLiveCache(key, maxsize, ttl, timer, typed)
        cache_active = decorator.is_active(key)

        if cache_active:
            return decorator[key]

        result = func(*args, **kwargs)
        decorator[key] = result
        decorator.forget_old_entries()
        return result

    return wrapper

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def wrapper(fn):
        cache = {}
        hits = {}
        misses = 0
        def call_and_cache(*args, **kwargs):
            nonlocal misses
            key = (args, kwargs)
            if key not in cache:
                cache[key] = fn(*args, **kwargs)
                hits[key] = timer()
            else:
                misses += 1
            return cache[key]
        def ttl_check():
            nonlocal cache, hits
            for key, (_, _) in cache.items():
                if hits[key] + ttl < timer():
                    hits.pop(key)
                    cache.pop(key)
        timer.attach(ttl_check)
        return call_and_cache
    return wrapper

