def extostr(e, max_level=30, max_path_level=5):
    exception_string = "Exception: {0}, {1}".format(e.type, e.message)
    stack_tuple = traceback.extract_tb(e.__traceback__)
    for i, frame in enumerate(stack_tuple):
        if i >= max_level:
            break
        exception_string += "\n{0}. {1} in {2} at line {3}".format(i + 1, frame.name, frame.filename, frame.lineno)

    path_tuple = traceback.extract_stack()
    for i, frame in enumerate(path_tuple):
        if i >= max_path_level:
            break
        exception_string += "\n{0}. {1} in {2} at line {3}".format(i + 1, frame.name, frame.filename, frame.lineno)

    return exception_string

