def extostr(cls, e, max_level=30, max_path_level=5):
    out = ""
    exc_type = type(e)
    out += f"{exc_type.__name__}: {e}"
    if len(e.args) > 0:
        out += "\nArguments: "
        for arg in e.args:
            out += f"{arg}, "
    out += "\nCall Stack: "
    for level in range(1, max_level):
        try:
            frame = sys._getframe(level)
        except ValueError:
            break
        out += f"\n  {frame.f_code.co_filename}:{frame.f_lineno} {frame.f_code.co_name}()"
    out += "\nException Path: "
    for path_level in range(1, max_path_level):
        try:
            frame = sys._getframe(path_level)
        except ValueError:
            break
        out += f"\n  {frame.f_code.co_filename}:{frame.f_lineno} {frame.f_code.co_name}()"
    return out

