    """
    Get attribute names and descriptions defined by this interface.

    :param all: Whether to include inherited names and descriptions.
    :type all: bool
    :return: Dictionary of attribute names and descriptions.
    :rtype: dict
    """

    namesAndDescriptions = {}

    for name in dir(self):
        if name.islower():
            continue
        desc = getattr(self, name).__doc__
        if not desc:
            continue
        if all:
            while 1:
                base = getattr(type(self), name, None)
