    if isinstance(params, abc.Mapping):
        out_params = {
            f'@{k}': v
            for k, v in params.items()
        }
    else:
        out_params = [f'@{i + 1}' for i, v in enumerate(params)]

    return (
        sql.format(*out_params),
        {
            'out_params': out_params
        }
    )

def format(sql, params):
    # Replace in-style parameters with out-style parameters
    if isinstance(params, dict):
        params = {k: [v] for k, v in params.items()}
    elif isinstance(params, list):
        params = {str(i + 1): v for i, v in enumerate(params)}
    else:
        raise ValueError("Unsupported parameter type: " + str(type(params)))

    # Replace parameter markers with placeholders
    for k, v in params.items():
        if isinstance(v, list):
            for i, w in enumerate(v):
                sql = sql.replace(f":{k}__in_{i}", f"%s", 1)
        else:
            sql = sql.replace(f":{k}", f"%s", 1)

    # Return formatted SQL query and converted parameters
    return (sql, params)

def formatted_sql(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of the in-style parameters.

    :param sql: The SQL query.
    :param params: The set of in-style parameters. It maps each parameter to value. If SQLParams.in_style is a named parameter style, then params must be a Mapping. If SQLParams.in_style is an ordinal parameter style, then params must be a Sequence.
    :return: The formatted SQL query and the set of converted out-style parameters.
    """
    if self.SQLParams.in_style == SQLParams.IN_STYLE_ORDINAL:
        new_params = []
        for index, value in enumerate(params):
            new_params.append(f":{index + 1}")
    elif self.SQLParams.in_style == SQLParams.IN_STYLE_NAMED:
        new_params = {}
        for key, value in params.items():
            new_params[f":{key}"] = value
    else:
        raise ValueError(f"Invalid in_style: {self.SQLParams.in_style}")
    formatted_sql = sql.format(**new_params)
    return formatted_sql and new_params

def format(sql: AnyStr, params: Union[Dict[AnyStr, Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[AnyStr, Any], Sequence[Any]]]:
	# Convert the SQL query to use out-style parameters instead of in-style parameters
	if self.in_style == 'named':
		if not isinstance(params, dict):
			raise TypeError("'params' must be a dictionary when using named parameter style")
		formatted_params = {f"@{key}": value for key, value in params.items()}
	else:
		if not isinstance(params, list):
			raise TypeError("'params' must be a list when using ordinal parameter style")
		formatted_params = params

	# Replace the in-style placeholders with the out-style ones
	formatted_sql = sql.replace('?', '@{}')
	for key, value in formatted_params.items():
		formatted_sql = formatted_sql.replace(key, str(value))

	return formatted_sql, formatted_params

def formatmany(sql, many_params):
    # Convert the SQL query to use the out-style parameters instead of the in-style parameters
    params = []
    for p in many_params:
        # Create a dictionary to hold the out-style parameters
        out_params = {}
        # Iterate over the in-style parameters
        for k, v in p.items():
            # If the parameter is not a named parameter, add it to the list of out-style parameters
            if not isinstance(k, str):
                out_params[k] = v
            # If the parameter is a named parameter, add it to the dictionary of out-style parameters
            else:
                out_params[k] = v
        # Add the converted out-style parameters to the list
        params.append(out_params)
    return sql, params

