def extract_number_and_supplment_from_issue_element(issue):
    """
    Extracts the number and supplement from the content of <issue>xxxx</issue>.
    """
    number = ""
    supplement = ""
    if issue.lower().startswith("supp"):
        supplement = "supplement"
    else:
        number = issue
    return (number, supplement)

def _extract_number_and_supplment_from_issue_element(issue):
    numbers = []
    supplements = []

    # Split the issue element into individual parts
    parts = issue.split(" ")

    # Iterate over the parts and extract the numbers and supplements
    for part in parts:
        # Check if the part is a number
        if part.isdigit():
            numbers.append(int(part))
        # Check if the part is a supplement
        elif "Suppl" in part:
            supplements.append(part)

    # Return a tuple containing the numbers and supplements
    return (numbers, supplements)

