def pretty(self, indent=0, debug=False):
    output = ""
    for key, value in self.__dict__.items():
        if isinstance(value, list) and value:
            output += f"{key}: \n"
            for item in value:
                output += f"{indent*2*' '}{item.__class__.__name__}:\n"
                if isinstance(item, dict):
                    output += pretty(item, indent+1, debug=debug)
                else:
                    output += f"{indent*2*' '}{item}\n"
        elif isinstance(value, dict) and value:
            output += f"{key}: \n"
            output += pretty(value, indent+1, debug=debug)
        else:
            output += f"{key}: {value}\n"
    return output

