def absorb(args):
    new_args = []
    for arg in args:
        if isinstance(arg, (And, Or)):
            new_args.append(absorb(arg.operands))
        else:
            new_args.append(arg)
    return new_args

def absorb(self, args):
    result = []
    for arg in args:
        if isinstance(arg, Or):
            result.append(self.absorb(arg.args))
        elif isinstance(arg, And):
            result.append(self.absorb(arg.args))
        else:
            result.append(arg)
    return result

def absorb(self, args):
    new_args = []
    for arg in args:
        if isinstance(arg, Disjunction):
            new_arg = Disjunction(arg.terms - {self}, arg.terms & {self})
        elif isinstance(arg, Conjunction):
            new_arg = Conjunction(arg.terms - {self}, arg.terms & {self})
        else:
            new_arg = arg
        new_args.append(new_arg)
    return new_args

