def _fromutc(self, dt):
    if dt.fold:
        return dt + self.utcoffset(dt) - self.normalize(dt - self.utcoffset(dt))
    else:
        return dt + self.utcoffset(dt)

def _fromutc(self, dt):
    if dt.tzinfo is not None:
        raise ValueError("dt.tzinfo is not None")
    if dt.fold:
        raise ValueError("dt.fold is True")
    return self.localize(dt)

def _fromutc(dt):
    if dt.fold:
        new_date = datetime(dt.year, dt.month, dt.day, dt.hour, dt.minute, dt.second, dt.microsecond, self.utc)
    else:
        new_date = datetime(dt.year, dt.month, dt.day, dt.hour, dt.minute, dt.second, dt.microsecond, self.utc)
    return new_date

def _fromutc(self, dt):
    # If the datetime is not ambiguous, we can just return it
    if not dt.fold:
        return dt.astimezone(self)

    # If the datetime is ambiguous, we need to determine if it's in a fold
    # state by checking if it's the first occurrence of the ambiguous
    # datetime. If it is, we subtract a day from the datetime.
    first_occurrence = dt.replace(fold=0)
    if(first_occurrence == dt):
        return dt.astimezone(self) - datetime.timedelta(days=1)
    else:
        return dt.astimezone(self)

def normalized(self):
