def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    import subprocess
    import shlex

    try:
        if isinstance(commands, str):
            commands = [commands]
        if isinstance(args, str):
            args = shlex.split(args)

        if verbose:
            print("Running command:", " ".join(commands + args))

        result = subprocess.run(commands + args, cwd=cwd, env=env)

        if hide_stderr:
