import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    result = subprocess.run(commands, args, cwd=cwd, env=env)
    if verbose:
        print("stdout:", result.stdout.decode())
        print("stderr:", result.stderr.decode())
    elif hide_stderr:
        print("stdout:", result.stdout.decode())
    else:
        print("Command finished with exit code", result.returncode)
    return result.returncode

def run_command(command, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    if not env:
        env = os.environ

    if isinstance(commands, list):
        for command in commands:
            command = shlex.split(command)
            run_command(command, cwd=cwd, verbose=verbose, hide_stderr=hide_stderr, env=env)
    else:
        command = shlex.split(commands)
        process = subprocess.Popen(command, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
        if verbose:
            print("Running command:", " ".join(command))
        stdout, stderr = process.communicate()
        if process.returncode != 0:
            if verbose:
                print("Stdout:", stdout.decode("utf-8"))
                print("Stderr:", stderr.decode("utf-8"))
                print("Command failed with exit code", process.returncode)
            return process.returncode
    return 0

