def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0

    for obj in self.objects:
        num_objects += 1
        if validate_objects:
            if not obj.validate():
                continue
        if check_digests:
            if obj.digest() != obj.expected_digest():
                continue
        good_objects += 1

    if show_warnings:
        if num_objects != good_objects:
            print(f"WARNING: {num_objects - good_objects} objects were not valid")

    return num_objects, good_objects

