    num_objects = 0
    good_objects = 0

    for obj in self.objects:
        num_objects += 1
        if validate_objects and not obj.validate():
            if show_warnings:
                print(f"Invalid object: {obj}")
        else:
            good_objects += 1

    for obj in self.objects:
