            good_objects += 1

    return num_objects, good_objects

def validate_hierarchy(validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0

    # Check storage root hierarchy
    for root in self.root_list:
        num_objects += 1
        if check_digests:
            # Check object digests
            if root.digest != root.child_digest:
                good_objects += 1
            else:
                root.check_digests(show_warnings)
        if validate_objects:
            # Validate object properties
            root.validate(show_warnings)

    return num_objects, good_objects

