def validate_version_inventories(self, version_dirs):
    # determine the latest version number
    latest_version = max(version_dirs)

    # create a map of version => inventory
    inventory_map = {}
    for version in version_dirs:
        inventory_map[version] = read_inventory(version)

    # create a map of version => digest
    digest_map = {}
    for version, digest in (inventory_map[latest_version].items()):
        digest_map[version] = digest

    # iterate over each version, skipping the latest one
    for version in range(len(version_dirs) - 1):
        # compare the digest of the current version to the root inventory
        if digest_map[version + 1] != digest_map[0]:
            raise InventoryMismatchError(
                f"Inventory for version {version + 1} is different from the root inventory"
            )

    # if we reach this point, all inventories have been validated successfully
    return True

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point."""
    content_hashes = {}

    # Keep a record of any content digests different from those in the root inventory
    # so that we can also check them when validating the content.
    root_inventory = self.root_inventory
    for version_dir in version_dirs:
        inventory = self.get_inventory(version_dir)
        content_hashes[version_dir] = {}

        for file_path, hash in inventory.items():
            if file_path not in root_inventory or hash != root_inventory[file_path]:
                content_hashes[version_dir][file_path] = hash

    return content_hashes

def validate_version_inventories(self, version_dirs):
    root_inventory = self.get_root_inventory()
    content_digests = set()
    for version in version_dirs:
        inventory = self.get_version_inventory(version)
        if inventory is None:
            raise ValueError(f"Missing inventory for version {version}")
        if not content_digests.issubset(inventory):
            raise ValueError(f"Inventory for version {version} does not contain all content digests")
        for content_digest in inventory:
            content_digests.add(content_digest)

def find_path_type(path):
    # Open the file at the given path
    with open(path) as f:
        # Read the first 8 lines of the file, which should contain the header
        lines = f.readlines(8)

        # Check if the header starts with "0=*"
        if lines[0].startswith("0="):
            # If it does, return the type of thing at the given path
            if lines[1].startswith("0=OCFL Storage Root"):
                return "root"
            elif lines[1].startswith("0=OCFL Object"):
                return "object"
            else:
                # If it's not a Storage Root or an Object, return "file"
                return "file"
        else:
            # If the header doesn't start with "0=*", return an error description
            return "Not an OCFL directory"

def find_path_type(path):
    if os.path.exists(path) and os.path.isdir(path):
        if os.path.basename(path).startswith("0="):
            if os.path.exists(os.path.join(path, "root/directory")):
                return "root"
            elif os.path.exists(os.path.join(path, "obj")):
                return "object"
            else:
                return "file"
        else:
            return "unknown"
    else:
        return "not found"

def find_path_type(path):
    try:
        namaste = os.listdir(path)[0]
        if namaste.startswith("0="):
            if "descriptive" in namaste:
                return "root"
            elif "inventory" in namaste:
                return "file"
            else:
                return "object"
        else:
            return "error"
    except IndexError:
        return "error"

def find_path_type(path: str) -> str:
    """Return a string indicating the type of thing at the given path.

    Args:
        path (str): The path to check for directory type.

    Returns:
        str: 'root' - looks like an OCFL Storage Root. 'object' - looks like an OCFL Object. 'file' - a file, might be an inventory. Other string explains the error description.
    """
    # Checks only "0=*" Namaste files to determine the directory type.
    try:
        with open(os.path.join(path, "0=*")) as f:
            namaste_file = f.read()
            if namaste_file.startswith("OCFL Object"):
                return "object"
            elif namaste_file.startswith("OCFL Storage Root"):
                return "root"
            else:
                return "file"
    except FileNotFoundError:
        return "file"
    except UnicodeDecodeError:
        return "error"
    except OSError:
        return "error"

