def deep_merge_nodes(nodes):
    result = []
    for node in nodes:
        key = node[0]
        value = node[1]
        if key.mype == NodeType.mapping and key.value:
            if any(v.value == key.value for v in result):
                result[result.index(v) if v.value == key.value else 0][1].value.append(key.value)
            else:
                result.append((key, value))
