def deep_merge_nodes(nodes):
    result = []
    for node in nodes:
        key = node[0]
        value = node[1]
        found = False
        for elem in result:
            if key.value == elem[0].value:
                found = True
                elem[1].value.extend(value.value)
                break
        if not found:
            result.append(node)
