def deep_merge_dicts(first, second):
    result = {}
    for k, v in first.items():
        if k insecond and isinstance(v, dict) and isinstance(second[k], dict):
            result[k] = deep_merge_dicts(v, second[k])
        else:
            result[k] = v
    for k, v in second.items():
        if k not in result:
            result[k] = v
    return result

