def parse_arguments(*unparsed_arguments):
    import argparse

    # Create a global parser
    global_parser = argparse.ArgumentParser(prog="parser")
    global_parser.add_argument("-v", "--version", action="version", version="1.0")

    # Create a subparser for each subcommand
    subparsers = global_parser.add_subparsers()
    subparsers.required = True
    subparsers.dest = "command"

    parser_foo = subparsers.add_parser("foo", help="foo subcommand")
    parser_foo.add_argument("-a", "--foo", type=int)

    parser_bar = subparsers.add_parser("bar", help="bar subcommand")
    parser_bar.add_argument("-b", "--bar", type=str)

    parsed_arguments = global_parser.parse_args(unparsed_arguments)

    if parsed_arguments.command == "foo":
        return {
            "command": "foo",
            "foo": parsed_arguments.foo
        }
    elif parsed_arguments.command == "bar":
        return {
            "command": "bar",
            "bar": parsed_arguments.bar
        }
    else:
        return {
            "command": parsed_arguments.command,
            "foo": None,
            "bar": None
        }

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_args = {}
    remaining_args = []
    for arg in unparsed_arguments:
        for name, parser in subparsers.items():
            try:
                result = parser.parse_known_args(arg)
                parsed_args[name] = result[0]
                remaining_args = result[1]
                break
            except SystemExit:
                continue
    return parsed_args, remaining_args

