def parse_subparser_arguments(unparsed_arguments, subparsers):
    subparser_arguments = {}
    remaining_arguments = []

    for argument in unparsed_arguments:
        for name, subparser in subparsers.items():
            if subparser.prefix_chars and argument.startswith(subparser.prefix_chars):
                try:
                    subparser_arguments[name] = subparser.parse_args([argument[1:]] + remaining_arguments)
                    break
                except argparse.ArgumentError as error:
                    if error.message.startswith("invalid choice"):
                        continue
                    else:
                        raise

    remaining_arguments = [argument for argument in remaining_arguments if argument not in subparser_arguments]

    return subparser_arguments, remaining_arguments

