def deep_merge_nodes(nodes):
    result = []
    seen_keys = set()
    for key, value in nodes:
        if key.value in seen_keys:
            # If key already exists in seen_keys, we need to deep merge the values
            # for this key.
            result[key.value] = _deep_merge(result[key.value], value)
        else:
            # If key does not exist in seen_keys, we can simply append it to the result
            result.append((key, value))
            seen_keys.add(key.value)
    return result

def _deep_merge(target, source):
    if not isinstance(target, MappingNode):
        # If target is not a MappingNode, we can't perform deep merging so we just
        # return the last value for this key.
        return source
    for key, value in source.value:
        if key.value in target.value:
            target[key.value] = _deep_merge(target[key.value], value)
        else:
            target.value.append((key, value))
    return target

