    for node in nodes:
        key = node[0]
        value = node[1]

        # Check if the node value is a MappingNode
        if isinstance(value, ruamel.yaml.nodes.MappingNode):
            # Recursively deep merge any child node values corresponding to duplicate keys
            child_results = deep_merge_nodes([(key, child_node) for child_node in value.value])
            # Add the child nodes to the result, merging any colliding keys
            for child_key, child_value in child_results:
                existing_value = next((child_node for child_node in result if child_node[0].value == child_key.value), None)
                if existing_value is not None:
                    # If there is a colliding key with a non-MappingNode value, the last value wins
                    if not isinstance(existing_value[1], ruamel.yaml.nodes.MappingNode):
                        result[result.index(existing_value)] = (child_key, child_value)
                    # If both the new and existing values are MappingNodes, deep merge them
