def deep_merge_nodes(nodes):
    combined = {}
    for key, value in nodes:
        if key in combined:
            # If the key is already present in the combined dictionary, we need to merge the values
            if isinstance(value, (ruamel.yaml.nodes.MappingNode, ruamel.yaml.nodes.SequenceNode)):
                # If the current value is a mapping or sequence, we need to recursively merge the keys
                combined[key].value.update(value.value)
            else:
                # If the current value is not a mapping or sequence, we can simply override the previous value
                combined[key] = value
        else:
            # If the key is not already present in the combined dictionary, we can add it directly
            combined[key] = value
    return [
        (
            ruamel.yaml.nodes.ScalarNode(tag='tag:yaml.org,2002:str', value=key),
            ruamel.yaml.nodes.MappingNode(tag='tag:yaml.org,2002:map', value=value.value)
        )
        for key, value in combined.items()
    ]

