    for i in range(0, len(response), max_results):
        yield response[i:i + max_results]

def paging(response, max_results):
    num_pages = len(response) // max_results
    for i in range(num_pages):
        yield response[i * max_results:(i + 1) * max_results]

def paging(response, max_results):
    current_page = 1
    while current_page * max_results < len(response):
        yield response[current_page * max_results:(current_page + 1) * max_results]
        current_page += 1
    yield response[(current_page * max_results):]

def size_to_bytes(size: str) -> int:
    size_mapping = {
        "K": 1000,
        "M": 1000000,
        "G": 1000000000,
    }
    num = float(size[:-1])
    mult = size_mapping[size[-1]]
    return int(num * mult)

def size_to_bytes(size: str) -> int:
    """
    Convert human readable file size to bytes.

    Args:
        size (str): A string representing a human readable file size (e.g. '500K')

    Returns:
        int: A decimal representation of the file size
    """
    size_match = re.search(r'(\d+)(\w)', size)
    if size_match:
        size_val = float(size_match.group(1))
        size_unit = size_match.group(2).lower()
        if size_unit == 'k':
            return int(size_val * 1000)
        elif size_unit == 'm':
            return int(size_val * 1000000)
        elif size_unit == 'g':
            return int(size_val * 1000000000)
        else:
            return int(size_val)
    else:
        return int(size)

def size_to_bytes(size: str) -> int:
    """
    Convert human-readable file size to bytes.
    """
    multiplier = {'K': 1000, 'M': 1000000, 'G': 1000000000, 'T': 1000000000000}
    size, unit = size.split()
    return int(float(size) * multiplier[unit])

