def vertex3tuple(vertices):
    points = []
    for i in range(len(vertices)):
        j = i - 1
        if j < 0:
            j = len(vertices) - 1
        k = (i + 1) % len(vertices)
        points.append((vertices[i], vertices[j], vertices[k]))
    return points

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    string = ""
    while number > 0:
        remainder = number % len(alphabet)
        string = alphabet[remainder] + string
        number //= len(alphabet)
    if padding is not None and len(string) < padding:
        string = (padding - len(string)) * "0" + string
    return string

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    string = ''
    while number > 0:
        string = alphabet[number % len(alphabet)] + string
        number //= len(alphabet)
    if padding is not None:
        string = string.zfill(padding)
    return string

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    result = ""
    while number > 0:
        result = alphabet[number % len(alphabet)] + result
        number //= len(alphabet)
    if padding is not None:
        result = result.rjust(padding, "0")
    return result

