def calc_val(s, t='*'):
    """Calculate the value attached to s with supported operators

    :param s: The input string to calculate
    :type s: str
    :param t: Supported operators, default as '*'
    :type t: str
    :return: The calculated value
    :rtype: int
    """
    val = s.strip()
    val_list = [int(i) for i in re.findall(r'\d+', val)]
    ops = re.findall(r'\d+[*/]', val)
