def find_tags(text: str, replacer: callable = None) -> Tuple[Set[str], str]:
    tags = set()
    replaced_text = text

    # Ignore tags inside code blocks
    in_code_block = False

    # Iterate through each character in the text
    for char in text:
        # Check if we are inside a code block
        if char == '<' and not in_code_block:
            in_code_block = True
        elif char == '>' and in_code_block:
            in_code_block = False

        # Skip tags inside code blocks
        if in_code_block:
            continue

        # Check if we found a tag
        if char == '#':
            # Find the index of the next whitespace character
            for i, c in enumerate(text[char+1:]):
                if c.isspace():
                    break

            # Extract the tag word
            tag = text[char+1:char+1+i]

            # Add the tag to the set
            tags.add(tag)

            # Replace the tag with the replacer function (if passed)
            if replacer:
                replaced_text = replaced_text.replace(tag, replacer(tag), 1)

    return (tags, replaced_text)

def find_tags(text, replacer=None):
    tags = set()
    replaced_text = ""

    inside_code_block = False
    for i, char in enumerate(text):
        if char == '`':
            inside_code_block = not inside_code_block
        elif not inside_code_block and char == '#':
            tag = text[i:].split(' ', 1)[0]
            tags.add(tag)
            if replacer:
                replaced_text += replacer(tag)
            else:
                replaced_text += tag
            break

    if not replaced_text:
        replaced_text = text

    return set, replaced_text

def find_tags(text, replacer=None):
    tag_regex = r"<(\/?\w+?)>"
    tags = set()
    for tag in re.findall(tag_regex, text):
        if not tag.startswith("/"):
            tags.add(tag)
    if replacer:
        text = re.sub(tag_regex, lambda m: str(replacer(m.group(1))), text)
    return (tags, text)

def process_text_links(text):
    links = []
    for match in re.finditer(r"https?://\S+", text):
        link = match.group(0)
        links.append(("<a href='{link}'>Link #{len(links)}</a>".format(link=link)))
    return " ".join(links)

