import re

def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    sender_match = re.search(r"^@(?P<sendethandle>\S+)", sender_handle)
    entity_match = re.search(r"^@(?P<entityhandle>\S+)", entity_handle)
    if sender_match and entity_match:
        sender_handle = sender_match.group("sendethandle")
        entity_handle = entity_match.group("entityhandle")
        return sender_handle == entity_handle
    else:
        return False

