def verify_relayable_signature(public_key, doc, signature):
    # Use the public key to verify the signature
    if public_key.verify(signature, doc):
        # If the signature is valid, return True
        return True
    else:
        # If the signature is invalid, return False
        return False

def verify_relayable_signature(public_key, doc, signature):
    signed_elements = doc.element.xpath('//*[@Signature]', namespaces={'ns': 'http://www.w3.org/2000/09/xmldsig#'})
    signed_element = signed_elements[0]
    signed_element.validate()
    signature_value = signed_element.get('SignatureValue')
    if not cryptography.x509.load_der_x509_certificate(public_key, backend=cryptography.hazmat.backends.default_backend()).public_key().verify(b64decode(signature_value), b64decode(signature), padding.PKCS1v15(), hashes.SHA256()):
        return False
    else:
        return True

