def validate_from_content(spec_content):
    if spec_content is None:
        raise IRValidatorException("Cannot validate a None spec content")

    # extract mandatory fields from the spec content
    mandatory_fields = ["name", "version", "description", "flow", "stages"]
    for field in mandatory_fields:
        if field not in spec_content:
            raise IRValidatorException(f"'{field}' field is missing in the spec content")

    # validate `flow` and `stages` fields
    if "flow" not in spec_content or not isinstance(spec_content["flow"], list):
        raise IRValidatorException("'flow' field is missing or not a list")
    if "stages" not in spec_content or not isinstance(spec_content["stages"], list):
        raise IRValidatorException("'stages' field is missing or not a list")

    # validate `stages` fields
    for stage in spec_content["stages"]:
        if "name" not in stage or not isinstance(stage["name"], str):
            raise IRValidatorException("invalid stage name")

    # return the validated spec content
    return spec_content

