    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """

    # Validate that the arguments are consistent
    if len(cli_args) != len(answer_file_args):
        raise ValueError("CLI args and answer file args have different lengths")

    # Validate that the arguments are of the correct type
    if not isinstance(cli_args, dict) or not isinstance(answer_file_args, dict):
        raise TypeError("Expected dict type for CLI args and answer file args")

    # Validate that the arguments have the correct keys
    if set(cli_args.keys()) != set(answer_file_args.keys()):
        raise ValueError("CLI args and answer file args have different keys")

    # Validate that the arguments have the correct values
    for key, value in cli_args.items():
        if type(value) != type(answer_file_args[key]):
            raise ValueError("CLI args and answer file args have different types for key {}".format(key))
        if value != answer_file_args[key]:
            raise ValueError("CLI args and answer file args have different values for key {}".format(key))

    # Print the deprecation warnings
    for key in answer_file_args.keys():
        if key not in cli_args:
            print("WARNING: The argument {} is deprecated. Please use the equivalent CLI argument instead.".format(key))

