def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    import os
    import subprocess

    if verbose is not None:
        ansible_args.update({"verbose": verbose})

    if extra_vars is not None:
        ansible_args.update({"extra-vars": "{{ extra_vars }}")

    ansible_cmd = [
        "ansible-playbook",
        playbook_path,
    ]

    for key, value in ansible_args.items():
        ansible_cmd.extend(["-" + key, value])

    ansible_cmd = " ".join(ansible_cmd)

    return subprocess.check_output(ansible_cmd, shell=True)

