            if key == "ssl-cert":
                values_dict[key] = convert_to_path(value)
            elif key == "port":
                values_dict[key] = int(value)
        elif parser_name == "weave":
            if key == "shell":
                values_dict[key] = value.lower() == "true"
            elif key == "language":
                values_dict[key] = convert_to_weave_language_name(value)
            elif key == "temp_dir":
                values_dict[key] = convert_to_path(value)
            elif key == "timeout":
                values_dict[key] = int(value)
        else:
            values_dict[key] = value

def _convert_non_cli_args(parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """

    # Float arguments
    if values_dict['--one']:
        values_dict['--one'] = float(values_dict['--one'])
    if values_dict['--two']:
        values_dict['--two'] = float(values_dict['--two'])

    # Integer arguments
    if values_dict['--three']:
        values_dict['--three'] = int(values_dict['--three'])
    if values_dict['--four']:
        values_dict['--four'] = int(values_dict['--four'])

    # Boolean arguments
    if values_dict['--five']:
        values_dict['--five'] = bool(values_dict['--five'])
    if values_dict['--six']:
        values_dict['--six'] = bool(values_dict['--six'])

    return values_dict

