def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if values_dict:
        for arg, value in values_dict.items():
            # Check if the argument is a flag
            if value is True:
                # If the argument is a flag, set its value to True
                values_dict[arg] = True
            else:
                # Check if the argument has a specific type
                if arg in self.TYPES:
                    # Cast the value to the correct type
                    values_dict[arg] = self.TYPES[arg](value)
    return values_dict

def _convert_non_cli_args(parser_name, values_dict):
    # Cast values_dict to the correct types based on the parser_name
    if parser_name == 'main':
        for key, value in values_dict.items():
            if key == 'help':
                # no conversion needed
                continue
            elif key == 'arg':
                # cast to list
                values_dict[key] = [value]
            else:
                # cast to int
                values_dict[key] = int(value)
    elif parser_name == 'virsh':
        for key, value in values_dict.items():
            if key == 'uuid':
                # cast to list
                values_dict[key] = [value]
            else:
                # cast to int
                values_dict[key] = int(value)
    elif parser_name == 'ospd':
        for key, value in values_dict.items():
            if key == 'help' or key == 'usage':
                # no conversion needed
                continue
            else:
                # cast to int
                values_dict[key] = int(value)
    else:
        raise ValueError(f'Unsupported parser name: {parser_name}')

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    # Path to the plugin's spec file
    spec_path = os.path.join(plugin_dir, "spec.yaml")

    # Load the plugin spec from the file
    with open(spec_path, "r") as spec_file:
        spec = yaml.safe_load(spec_file)

    # Flatten the spec dictionary
    flat_spec = {
        key: value
        for key, value in spec.items()
        if isinstance(value, dict)
    }

    return flat_spec

