def get_plugin_spec_flatten_dict(plugin_dir):
    plugin_spec = None
    with open(plugin_dir + '/spec.yaml') as f:
        plugin_spec = yaml.safe_load(f)
    flattened_dict = {}
    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            for subkey, subvalue in value.items():
                flattened_dict[key + '/' + subkey] = subvalue
        else:
            flattened_dict[key] = value
    return flattened_dict

import os

def inject_config(self):
    config_path = os.getenv('CONFIG_PATH')
    if not config_path:
        os.environ['CONFIG_PATH'] = self.get_default_config_path()
        print(f'Environment variable CONFIG_PATH is not set, using {self.get_default_config_path()} as default.')
    else:
        print(f'Environment variable CONFIG_PATH is already set to {config_path}.')

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    config_path = os.getenv("CONFIG_PATH")
    if not config_path:
        config_path = os.path.join(os.path.expanduser("~"), ".config")
        os.environ["CONFIG_PATH"] = config_path

